// relance-radar : choisir les fils à relancer. Ne crée rien, ne envoie rien :
// rend une décision par fil (relancer ou ignorer, avec la raison).
const s = $('Réglages').first().json;
const me = String(s.mon_adresse || '').trim().toLowerCase();
const waitDays = Number(s.jours_avant_relance || 5);
const maxFollow = Number(s.relances_max || 2);
const excluded = String(s.liste_exclusion || '').toLowerCase().split(/[\s,;]+/).filter(Boolean);
const signature = String(s.signature || '').trim();
const now = s.date_du_jour ? new Date(String(s.date_du_jour) + 'T12:00:00Z') : new Date();
const DAY = 86400000;
const dayOf = d => Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());

const addr = v => {
  const m = String(v || '').match(/<([^>]+)>/);
  return (m ? m[1] : String(v || '')).trim().toLowerCase();
};
const firstName = v => {
  const m = String(v || '').match(/^\s*"?([^"<,@]+?)"?\s*</);
  return m ? m[1].trim().split(/\s+/)[0] : '';
};
const labelsOf = m => (m.labels || m.labelIds || []).map(l => String(l.id || l.name || l).toUpperCase());
const dateOf = m => new Date(Number(m.internalDate) || Date.parse(m.Date || m.date || 0));
const fr = d => d.toLocaleDateString('fr-CA', { day: 'numeric', month: 'long', timeZone: 'UTC' });
const isExcluded = a => excluded.some(x => (x.startsWith('@') ? a.endsWith(x) : a === x));

// Les messages arrivent un par item (ou groupés dans messages[]) : on les range par fil.
const threads = {};
for (const it of $input.all()) {
  const j = it.json;
  const list = Array.isArray(j.messages) ? j.messages : [j];
  for (const m of list) {
    const t = m.threadId || j.id;
    (threads[t] = threads[t] || []).push(m);
  }
}

const out = [];
for (const [threadId, msgs] of Object.entries(threads)) {
  msgs.sort((a, b) => dateOf(a) - dateOf(b));
  const drafts = msgs.filter(m => labelsOf(m).includes('DRAFT'));
  const real = msgs.filter(m => !labelsOf(m).includes('DRAFT'));
  const mine = real.filter(m => addr(m.From) === me);
  const others = real.filter(m => addr(m.From) !== me);
  const first = mine[0];
  const decision = { threadId, a: first ? addr(first.To) : '', sujet: String((first || msgs[0]).Subject || '').replace(/^\s*((re|tr|fwd?)\s*:\s*)+/i, '') };
  const skip = raison => out.push({ json: { ...decision, action: 'ignorer', raison } });

  if (!first) { skip("aucun message envoyé par toi dans ce fil"); continue; }
  if (others.some(m => /mailer-daemon|postmaster/i.test(addr(m.From)))) { skip('adresse en erreur (message non distribué)'); continue; }
  if (others.length) { skip('a répondu'); continue; }
  if (isExcluded(decision.a)) { skip("sur ta liste d'exclusion"); continue; }
  if (drafts.length) { skip('un brouillon de relance attend déjà dans ce fil'); continue; }
  const done = mine.length - 1;
  if (done >= maxFollow) { skip(`déjà relancé ${done} fois, maximum atteint`); continue; }
  const last = mine[mine.length - 1];
  const days = Math.round((dayOf(now) - dayOf(dateOf(last))) / DAY);
  if (days < waitDays) { skip(`trop récent (${days} jours, attente de ${waitDays})`); continue; }

  const n = done + 1;
  const hello = firstName(first.To) ? `Bonjour ${firstName(first.To)},` : 'Bonjour,';
  const sentences = n === 1
    ? [
        `Je reviens vers vous au sujet de mon message du ${fr(dateOf(first))}, « ${decision.sujet} ».`,
        "Est-ce toujours d'actualité de votre côté ?",
        'Une réponse en un mot me suffit : oui, non ou plus tard.',
      ]
    : [
        `Je n'ai pas eu de retour sur « ${decision.sujet} », envoyé le ${fr(dateOf(first))}.`,
        "Si ce n'est plus une priorité, dites-le-moi et je ferme le dossier de mon côté.",
        "Si ça l'est encore, je vous propose un court appel cette semaine pour avancer.",
      ];
  out.push({
    json: {
      ...decision,
      action: 'relancer',
      raison: `${days} jours sans réponse, relance n°${n}`,
      relance_numero: n,
      jours_sans_reponse: days,
      objet: `Re: ${decision.sujet}`,
      message: [hello, '', ...sentences, '', signature].join('\n').trim(),
    },
  });
}
return out;
